{
  "technical_and_design_decisions": [
    "All copied Fabric code in the SDK will be replaced with imports of official, upstreamed Hyperledger Fabric Go modules to eliminate local code duplication and reduce long-term maintenance burden.",
    "Any required changes to upstream Fabric code (e.g., exporting unexported functions/structures needed by the SDK) will be submitted as small, focused PRs to official Fabric repositories to ensure long-term compatibility and maintainability.",
    "The temporary go.mod chaincode workaround (U6) will be implemented with a build-time configuration flag to enable easy disabling and removal once the SDK fully transitions to Go modules, minimizing long-term technical debt.",
    "All existing public SDK APIs will be preserved to ensure backward compatibility for existing SDK users, with no breaking changes to the SDK's external interface.",
    "Go module version pinning will be used for all external Fabric dependencies to ensure consistent builds and avoid unexpected breaking changes from unvetted upstream updates."
  ],
  "assumptions": [
    "Official Hyperledger Fabric maintainers will accept small, focused PRs to export required unexported functions/structures within the estimation timeline, with no long-running upstream negotiation required.",
    "Existing modifications to copied Fabric code in the SDK are either redundant (already present in upstream Fabric) or can be upstreamed without significant changes to SDK functionality.",
    "The temporary go.mod chaincode workaround will only be required for a maximum of 3 months, so no long-term support or complex edge case handling is needed for this feature.",
    "All existing SDK unit and integration tests are compatible with upstream Fabric module APIs, with only minor adjustments needed for import path changes and small API differences.",
    "The SDK's existing Go version requirements are compatible with the Go version requirements of the upstream Fabric modules being imported, so no Go version upgrades are required."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Audit existing copied code and map usage to upstream equivalents",
      "activity_description": "Review all copied code in the SDK's internal/ and third_party/ directories referenced in the user stories, catalog all functions, structures, and interfaces used by the SDK, and identify corresponding components in official Hyperledger Fabric Go modules.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A2",
      "activity_name": "Upstream required changes to Fabric repositories",
      "activity_description": "Develop, submit, and iterate on small PRs to official Hyperledger Fabric repos to export any unexported functions/structures required by the SDK that are not currently part of the public Fabric API.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A3",
      "activity_name": "Replace copied gossip utilities with external imports",
      "activity_description": "Remove the modified gossip protoext and discovery client code from internal/github.com/hyperledger/fabric/gossip, update all SDK code that references these components to import the upstream Fabric gossip module, and resolve any API mismatches between the modified local copy and upstream code.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A4",
      "activity_name": "Replace copied cauthdsl utilities with external imports",
      "activity_description": "Remove the copied cauthdsl code from third_party/github.com/hyperledger/fabric/common/cauthdsl, update all SDK references to use the upstream Fabric common cauthdsl module, and fix any minor API mismatches.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A5",
      "activity_name": "Replace copied ccprovider structures with external imports",
      "activity_description": "Remove copied ccprovider code from third_party/github.com/hyperledger/fabric/core/common/ccprovider, update SDK references to use the upstream Fabric core ccprovider module, and resolve any API mismatches.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A6",
      "activity_name": "Replace copied ledger structures with external imports",
      "activity_description": "Remove copied ledger code from third_party/github.com/hyperledger/fabric/core/ledger, update SDK references to use the upstream Fabric core ledger module, and resolve any API mismatches.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A7",
      "activity_name": "Replace copied common utilities with external imports",
      "activity_description": "Remove copied common and core common utility code from internal/github.com/hyperledger/fabric/common and internal/github.com/hyperledger/fabric/core, update all SDK references to use upstream Fabric common/core modules, and fix any API mismatches.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A8",
      "activity_name": "Replace copied configtxgen functions with external imports",
      "activity_description": "Remove modified configtxgen code from internal/github.com/hyperledger/fabric/sdkinternal/configtxgen and pkg/fab/resource/configtx.go, update SDK references to use the upstream Fabric configtxgen module, and resolve any API mismatches.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A9",
      "activity_name": "Replace copied configtxlator functions with external imports",
      "activity_description": "Remove copied configtxlator code from internal/github.com/hyperledger/fabric/sdkinternal/configtxlator, update SDK references to use the upstream Fabric configtxlator module, and fix any API mismatches.",
      "most_likely_effort": 10
    },
    {
      "activity_id": "A10",
      "activity_name": "Implement temporary go.mod chaincode workaround",
      "activity_description": "Add build-time logic to the SDK to honor go.mod files included in chaincode packages during the transition to Go modules, implement a deprecation configuration flag to disable the workaround when no longer needed, and add inline documentation noting the temporary nature of the feature.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A11",
      "activity_name": "Update SDK tests for new import structure",
      "activity_description": "Modify all existing unit and integration tests to work with the new external import paths, fix any test failures caused by API changes or import updates, and add new tests to validate the temporary go.mod chaincode workaround functionality.",
      "most_likely_effort": 20
    },
    {
      "activity_id": "A12",
      "activity_name": "Update documentation and run full regression testing",
      "activity_description": "Update all relevant SDK documentation (README, API docs, migration guides) to reflect the removal of copied code, new external dependency requirements, and the temporary go.mod workaround. Run full end-to-end regression testing across all supported Fabric versions to ensure no functionality is broken by the changes.",
      "most_likely_effort": 12
    }
  ],
  "reported_total": {
    "most_likely_effort": 166
  }
}

